"use strict";(globalThis.webpackChunkmomosdk=globalThis.webpackChunkmomosdk||[]).push([[567],{5226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"1.0","label":"1.0","banner":null,"badge":true,"noIndex":false,"className":"docs-version-1.0","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/","label":"Overview","docId":"index","unlisted":false},{"type":"category","label":"Engineering","collapsible":false,"collapsed":false,"items":[{"type":"category","label":"Getting Started","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/engineering/getting-started/developer-setup","label":"Developer Setup","docId":"engineering/getting-started/developer-setup","unlisted":false},{"type":"link","href":"/engineering/getting-started/publishing-sdk","label":"SDK Publishing","docId":"engineering/getting-started/publishing-sdk","unlisted":false},{"type":"link","href":"/engineering/getting-started/testing","label":"Code Testing","docId":"engineering/getting-started/testing","unlisted":false}],"href":"/category/getting-started"},{"type":"category","label":"Contributions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/engineering/contributions/code-contribution","label":"Code Contributions","docId":"engineering/contributions/code-contribution","unlisted":false},{"type":"link","href":"/engineering/contributions/code-standards","label":"Code Standards","docId":"engineering/contributions/code-standards","unlisted":false}],"href":"/category/contributions"}],"href":"/category/engineering"},{"type":"category","label":"Documentation","collapsible":false,"collapsed":false,"items":[{"type":"link","href":"/Documentation/usage","label":"Library Setup","docId":"Documentation/usage","unlisted":false},{"type":"category","label":"Library Usage","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/Documentation/api-reference/authentication","label":"Authentication","docId":"Documentation/api-reference/authentication","unlisted":false},{"type":"link","href":"/Documentation/api-reference/collection","label":"Collection","docId":"Documentation/api-reference/collection","unlisted":false},{"type":"link","href":"/Documentation/api-reference/disbursements","label":"Disbursements","docId":"Documentation/api-reference/disbursements","unlisted":false},{"type":"link","href":"/Documentation/api-reference/remittance","label":"Remittance","docId":"Documentation/api-reference/remittance","unlisted":false},{"type":"link","href":"/Documentation/api-reference/account","label":"Account","docId":"Documentation/api-reference/account","unlisted":false}],"href":"/category/library-usage"},{"type":"link","href":"/Documentation/kdocs","label":"Code Documentation (`Kdocs`)","docId":"Documentation/kdocs","unlisted":false}],"href":"/category/documentation"}]},"docs":{"Documentation/api-reference/account":{"id":"Documentation/api-reference/account","title":"Library Usage \u2014 Account","description":"Account APIs retrieve subscriber information and validate account status. They are shared across all product types (Collection, Disbursements, Remittance) \u2014 pass the appropriate productType and productSubscriptionKey for the product you are using.","sidebar":"tutorialSidebar"},"Documentation/api-reference/authentication":{"id":"Documentation/api-reference/authentication","title":"Library Usage \u2014 Authentication","description":"The authentication flow provisions all credentials needed before any product API can be called. Every step is exposed as a Flow> except where noted; collect the flow inside a coroutine scope and handle Loading, Success, and Error states.","sidebar":"tutorialSidebar"},"Documentation/api-reference/collection":{"id":"Documentation/api-reference/collection","title":"Library Usage \u2014 Collection","description":"Collection APIs let you request payments from customers, check transaction status, send delivery notifications, manage invoices, and handle pre-approvals.","sidebar":"tutorialSidebar"},"Documentation/api-reference/disbursements":{"id":"Documentation/api-reference/disbursements","title":"Library Usage \u2014 Disbursements","description":"Disbursements APIs let you send money to Mobile Money accounts (transfers), credit accounts directly (deposits), and reverse transactions (refunds), plus query the status of each.","sidebar":"tutorialSidebar"},"Documentation/api-reference/remittance":{"id":"Documentation/api-reference/remittance","title":"Library Usage \u2014 Remittance","description":"Remittance APIs let you send international transfers to Mobile Money accounts and check their status. Two flows are available: the legacy V1 transfer and the V2 cashTransfer, which extends the payload with optional KYC fields about the sending party for cross-border compliance.","sidebar":"tutorialSidebar"},"Documentation/kdocs":{"id":"Documentation/kdocs","title":"Code Documentation (Kdocs)","description":"We utilize Dokka to generate comprehensive Kotlin code documentation for the MTN MOMO API SDK. This tool ensures that all code added to the repository is accompanied by corresponding documentation, significantly enhancing usability and maintainability for developers.","sidebar":"tutorialSidebar"},"Documentation/usage":{"id":"Documentation/usage","title":"Library Setup","description":"This page covers the documentation site infrastructure \u2014 how it is built, continuously deployed, and how to preview changes locally. The site is generated with Docusaurus and published automatically via GitHub Actions on every push to develop. Documentation source lives in the versioneddocs/ directory; the current version is 1.0.","sidebar":"tutorialSidebar"},"engineering/contributions/code-contribution":{"id":"engineering/contributions/code-contribution","title":"Code Contributions","description":"Contributions to the MTN MoMo Android SDK are not only welcome but encouraged! We believe that collaboration is key to improving our project and making it more robust. If you have ideas, improvements, or bug fixes, please feel free to submit a Pull Request (PR). However, for significant changes, we recommend opening an issue first to discuss your proposed modifications. This helps ensure that your contributions align with the project\'s goals and standards.","sidebar":"tutorialSidebar"},"engineering/contributions/code-standards":{"id":"engineering/contributions/code-standards","title":"Code Standards","description":"Establishing clear code standards is essential for maintaining a high-quality codebase that is easy to read, understand, and maintain. These standards help ensure consistency across contributions, making it easier for all developers to collaborate effectively. Below are the key areas of focus for our code standards.","sidebar":"tutorialSidebar"},"engineering/getting-started/developer-setup":{"id":"engineering/getting-started/developer-setup","title":"Getting Started","description":"---","sidebar":"tutorialSidebar"},"engineering/getting-started/publishing-sdk":{"id":"engineering/getting-started/publishing-sdk","title":"SDK Publishing","description":"Publishing the MTN MOMO API SDK is handled automatically by a GitHub Actions CI pipeline using the standard Gradle maven-publish plugin. Pushing a git tag triggers the workflow, which runs tests, signs artifacts, and publishes to Maven Central \u2014 no manual steps required.","sidebar":"tutorialSidebar"},"engineering/getting-started/testing":{"id":"engineering/getting-started/testing","title":"Code Testing","description":"The MTN MoMo Android SDK is designed with a robust testing framework that includes automated style checks, code coverage assessments, unit tests, and user interface/integration tests. These tests are crucial for maintaining code quality and ensuring that new changes do not introduce bugs. All tests are executed through GitHub Actions whenever a pull request is submitted. It is essential that all tests pass successfully for a pull request to be merged without requiring an admin override, thereby maintaining the integrity of the codebase.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"index","description":"---","sidebar":"tutorialSidebar"}}}}')}}]);